-- 阶段5：招生内容与AI建议/配额；0001–0021原样保留。
CREATE TABLE content_items(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,type TEXT NOT NULL,subject TEXT NOT NULL,scene TEXT,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','ready','copied','published')),doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),author_id TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE INDEX content_list ON content_items(tenant_id,status,updated_at DESC,id);
CREATE INDEX content_author ON content_items(tenant_id,author_id,updated_at DESC);
CREATE TABLE content_revisions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,content_id TEXT NOT NULL,seq INTEGER NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),action TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,content_id,seq),FOREIGN KEY(tenant_id,content_id) REFERENCES content_items(tenant_id,id));
CREATE TRIGGER content_revision_immutable BEFORE UPDATE ON content_revisions BEGIN SELECT RAISE(ABORT,'content_revision_immutable'); END;
CREATE TABLE ai_settings(id TEXT PRIMARY KEY,fast_daily_limit INTEGER NOT NULL DEFAULT 80 CHECK(fast_daily_limit>=0),deep_daily_limit INTEGER NOT NULL DEFAULT 50 CHECK(deep_daily_limit>=0),fast_model TEXT,deep_model TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL);
INSERT INTO ai_settings(id,updated_at,updated_by) VALUES('main',0,'migration0022');
CREATE TABLE ai_quota_daily(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,date TEXT NOT NULL,tier TEXT NOT NULL CHECK(tier IN('fast','deep')),used INTEGER NOT NULL DEFAULT 0 CHECK(used>=0),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,date,tier));
CREATE TABLE ai_requests(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,user_id TEXT NOT NULL,idem_key TEXT NOT NULL,request_hash TEXT NOT NULL,path TEXT NOT NULL,batch_parent_id TEXT,status TEXT NOT NULL CHECK(status IN('pending','done','failed')),hold_id TEXT NOT NULL,deadline_at INTEGER NOT NULL,response TEXT,cache_expires_at INTEGER,receipt_json TEXT,created_at INTEGER NOT NULL,finished_at INTEGER,retain_until INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,user_id,idem_key));
CREATE INDEX ai_pending_user ON ai_requests(tenant_id,user_id,status,deadline_at);
CREATE INDEX ai_request_retention ON ai_requests(tenant_id,retain_until);
CREATE TABLE ai_quota_holds(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL UNIQUE,date TEXT NOT NULL,tier TEXT NOT NULL,user_id TEXT NOT NULL,request_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('held','settled','released','expired')),expires_at INTEGER NOT NULL,settled_at INTEGER,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,request_id) REFERENCES ai_requests(tenant_id,id));
CREATE INDEX ai_live_holds ON ai_quota_holds(tenant_id,date,tier,status,expires_at);
CREATE TABLE ai_usage(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,hold_id TEXT UNIQUE,request_id TEXT,user_id TEXT NOT NULL,date TEXT NOT NULL,tool TEXT NOT NULL,action TEXT NOT NULL,tier TEXT NOT NULL,model TEXT NOT NULL,prompt_tokens INTEGER NOT NULL DEFAULT 0,completion_tokens INTEGER NOT NULL DEFAULT 0,duration_ms INTEGER NOT NULL,result TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE INDEX ai_usage_stats ON ai_usage(tenant_id,date,tool,tier,result);
CREATE TRIGGER ai_usage_immutable BEFORE UPDATE ON ai_usage BEGIN SELECT RAISE(ABORT,'ai_usage_immutable'); END;
